func TestReleasedV6LockPreservesMCPOrderAndSkillSelection(t *testing.T) {
	// Generated by v0.7.2 with a skill group, Pi package order, and two MCP bindings.
	const path = "testdata/v0.7.2-mcp-order-and-skills.lock.toml"
	legacy, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	got, err := Load(t.Context(), path)
	if err != nil {
		t.Fatal(err)
	}

	// These released paths are stable tokens, so their v7 pointers have the same spelling.
	projected := replaceLockfileStringOnce(t, string(legacy), "version = 6", "version = 7")
	for _, path := range []string{"/mcpServers/context7", "/mcpServers/pi-context"} {
		projected = replaceLockfileStringOnce(t, projected, `content_path = "`+path+`"`, `key_path = "`+path+`"`)
	}
	want, err := DecodeForRelock(t.Context(), []byte(projected))
	if err != nil {
		t.Fatalf("v7 projection of the released lock: %v", err)
	}
	if marshalLockfileForTest(t, got) != marshalLockfileForTest(t, want) {
		t.Fatal("v6 read changed the released locked plan")
	}
}

func TestV6LockPreservesGitRepairAndS3Version(t *testing.T) {
	git := repairedSkillSubjectContract(t)
	local := directSkillSubjectContract(t, "remote")
	canonical := marshalLockfileForTest(t, lockfileWithSubjects(t, git, local))
	legacy := replaceLockfileStringOnce(t, canonical, currentLockfileVersionEnvelope(), "version = 6")
	// Exact supply and its derivation both name the same versioned S3 object.
	const localSupply = `source_id = "local:skills/remote?mode=vendor"`
	if strings.Count(legacy, localSupply) != 2 {
		t.Fatal("local skill fixture lacks its exact supply and derivation")
	}
	const s3Source = "s3:s3://fixture-bucket/skills/remote.tar.gz?format=tar.gz&region=us-east-1"
	const s3Version = "object-version-fixture"
	legacy = strings.ReplaceAll(legacy, localSupply, `source_id = "`+s3Source+`"`+"\n"+`resolved_ref = "`+s3Version+`"`)

	file, err := Load(t.Context(), writeLockfileText(t, legacy))
	if err != nil {
		t.Fatal(err)
	}
	subjects := file.Locked.Subjects()
	if len(subjects) != 2 || !subjects[0].Equal(git) {
		t.Fatal("v6 read changed Git supply or its repair recipe")
	}
	s3, present := subjects[1].ExactSupply()
	wantS3Bytes, _ := local.ExactSupply()
	if !present || s3.SourceID() != s3Source || s3.ResolvedRef() != s3Version ||
		s3.ContentHash() != wantS3Bytes.ContentHash() || s3.Kind() != wantS3Bytes.Kind() {
		t.Fatalf("v6 read changed S3 supply: %+v", s3)
	}
}

func TestV6TranslationEnforcesLegacyAggregatePathGrammar(t *testing.T) {
	for _, test := range []struct {
		legacy  string
		pointer string
	}{
		{legacy: "/mcpServers/tool-1", pointer: "/mcpServers/tool-1"},
		{legacy: "/mcpServers/a~1b"},           // RFC 6901 escape syntax was not legal in v6.
		{legacy: `/mcpServers/with\backslash`}, // Legal in a native pointer, not a v6 aggregate path.
		{legacy: "/"},
	} {
		t.Run(test.legacy, func(t *testing.T) {
			value := v6RealizationDTO{ManagedAggregate: &v6ManagedAggregateContributionDTO{ContentPath: test.legacy}}
			converted, err := value.toV7()
			if test.pointer == "" {
				if err == nil {
					t.Fatal("invalid v6 aggregate path was accepted")
				}
				return
			}
			if err != nil || converted.ManagedAggregate.KeyPath != test.pointer {
				t.Fatalf("conversion of %q = %+v, %v, want %q", test.legacy, converted, err, test.pointer)
			}
		})
	}
}

func TestV6LockRejectsMixedAndNoncanonicalContents(t *testing.T) {
	canonical := marshalLockfileForTest(t, lockfileWithSubjects(t, claudeProjectMCPSubjectContract(t)))
	legacy := replaceLockfileStringOnce(t, canonical, currentLockfileVersionEnvelope(), "version = 6")
	legacy = replaceLockfileStringOnce(t, legacy, `key_path = "/mcpServers/context7"`, `content_path = "/mcpServers/context7"`)
	baseline, err := loadContent(t.Context(), []byte(legacy))
	if err != nil || baseline.Locked.Len() != 1 {
		t.Fatalf("valid schema 6 MCP lock = %+v, %v", baseline, err)
	}

	for _, test := range []struct {
		name, from, to string
	}{
		{"current key", "content_path =", "key_path ="},
		{"new subject field", `ownership = "manifest"`, "agent_config_placement = {}\nownership = \"manifest\""},
		{"unknown operation field", `operation = "observe"`, "future_operation_field = true\noperation = \"observe\""},
		{"extra empty list", `operation = "observe"`, "preconditions = []\noperation = \"observe\""},
	} {
		t.Run(test.name, func(t *testing.T) {
			content := replaceLockfileStringOnce(t, legacy, test.from, test.to)
			file, err := loadContent(t.Context(), []byte(content))
			if !errors.Is(err, ErrUnusableV6) || file.Version != 0 || file.Locked.Len() != 0 {
				t.Fatalf("invalid input returned %+v, %v", file, err)
			}
		})
	}
}

func TestV6AdmissionPreservesLimitsAndCancellation(t *testing.T) {
	deep := lockfileWithVersionAndNestedInlineTables(6, tomlsyntax.MaximumDepth+1)
	if _, err := loadContent(t.Context(), deep); !errors.Is(err, tomlsyntax.ErrMaximumDepthExceeded) {
		t.Fatalf("over-limit v6 = %v, want the structure limit", err)
	}
	ctx, cancel := context.WithCancel(t.Context())
	cancel()
	if _, err := loadV6Content(ctx, []byte("version = 6\n[[\n")); !errors.Is(err, context.Canceled) {
		t.Fatalf("cancelled v6 read = %v, want context cancellation", err)
	}
}

func TestV6CompatibilityIsOnlyForLockedPlanReaders(t *testing.T) {
	const legacy = "version = 6\n\n[locked]\n"
	path := writeLockfileText(t, legacy)
	file, err := Load(t.Context(), path)
	if err != nil || file.Version != lock.CurrentVersion {
		t.Fatalf("regular v6 reader returned %+v, %v", file, err)
	}
	contributions, err := currentContributions(t.Context())
	if err != nil {
		t.Fatal(err)
	}
	codec, err := NewCodec(contributions)
	if err != nil {
		t.Fatal(err)
	}
	for name, decode := range map[string]func(context.Context, []byte) (lock.File, error){
		"catalog codec": codec.Decode,
		"relock":        DecodeForRelock,
	} {
		t.Run(name, func(t *testing.T) {
			_, err := decode(t.Context(), []byte(legacy))
			var versionErr UnsupportedVersionError
			if !errors.As(err, &versionErr) || versionErr.Found != 6 || !versionErr.RelockSupported() {
				t.Fatalf("schema 6 read returned %v, want opaque older schema", err)
			}
		})
	}
	replacement, err := ReadReplacementContent(t.Context(), path)
	if err != nil || !bytes.Equal(replacement, []byte(legacy)) {
		t.Fatalf("replacement read changed the original bytes: %v", err)
	}
}
